 static final int BG=Color.rgb(4,5,7),CARD=Color.rgb(15,17,21),ORANGE=Color.rgb(255,112,8),WHITE=Color.rgb(246,246,248),MUTED=Color.rgb(145,149,158),GREEN=Color.rgb(34,210,104),RED=Color.rgb(245,66,83);
 LinearLayout page,nav; TextView state,power,workers,shares,temp,battery,balance,network,elapsed; Button start; boolean running=false; long started; Handler timer=new Handler(Looper.getMainLooper()); Runnable tick=new Runnable(){public void run(){if(running&&elapsed!=null){long d=Math.max(0,System.currentTimeMillis()-started)/1000;elapsed.setText(String.format(Locale.ROOT,"%02d:%02d:%02d",d/3600,(d/60)%60,d%60));}timer.postDelayed(this,1000);}}; ExecutorService io=Executors.newSingleThreadExecutor(); LuckPoolClient pool=new LuckPoolClient(); SharedPreferences appPrefs,poolPrefs;
 @Override public void onCreate(Bundle b){super.onCreate(b);appPrefs=getSharedPreferences("marsx_premium",MODE_PRIVATE);poolPrefs=getSharedPreferences("vrsc_watch",MODE_PRIVATE);running=appPrefs.getBoolean("session_active",false);started=appPrefs.getLong("session_started",0);if(appPrefs.getBoolean("consent_ok",false))shell();else showSplash();}
