 void consent(){ScrollView sv=new ScrollView(this);sv.setFillViewport(true);LinearLayout r=base();r.setPadding(dp(24),dp(24),dp(24),dp(24));sv.addView(r);r.addView(logo());r.addView(t("MARS-X'e Hoş Geldin",27,ORANGE));String[] rows={"◉  Kolay Başla\n     Tek dokunuşla oturumu yönet","◉  Gerçek İstatistik\n     Doğrulanmış havuz verileri","◉  %3 Davet Kazancı\n     Arkadaşlarını davet et","◉  Güvenli ve Şeffaf\n     Kontrol her zaman sende"};for(String s:rows)r.addView(t(s,16,WHITE));CheckBox ok=new CheckBox(this);ok.setText("Koşulları ve gizlilik bildirimini kabul ediyorum");ok.setTextColor(MUTED);r.addView(ok);Button b=btn("KABUL ET VE DEVAM ET");r.addView(b,new LinearLayout.LayoutParams(-1,dp(58)));b.setOnClickListener(v->{if(ok.isChecked()){appPrefs.edit().putBoolean("consent_ok",true).apply();shell();}else Toast.makeText(this,"Onay gerekli.",Toast.LENGTH_SHORT).show();});setContentView(sv);}
