 void statsCard(){LinearLayout s=card();s.addView(t("GÜÇ VE PERFORMANS",18,WHITE));LinearLayout row=new LinearLayout(this);power=metric(row,"Güç","— Sol/s");workers=metric(row,"Aktif Worker","—");s.addView(row);LinearLayout row2=new LinearLayout(this);shares=metric(row2,"Paylaşılan İş","—");temp=metric(row2,"Sıcaklık","43°C sınır");s.addView(row2);battery=t("Pil alt limiti %15  •  Cihaz pili —",13,MUTED);s.addView(battery);network=t("Ağ durumu  •  Veri bekleniyor",13,MUTED);s.addView(network);Button p=btn("CİHAZ / HAVUZ DURUMU");p.setOnClickListener(v->powerPage());s.addView(p);Button g=btn("GELİŞMİŞ GRAFİKLER");g.setOnClickListener(v->graphs());s.addView(g);page.addView(s);}
