 void earn(){head("KAZANÇ İSTATİSTİKLERİ");LinearLayout c=card();c.addView(t("Günlük     Haftalık     Aylık     Tümü",14,ORANGE));c.addView(t("0.000000 MARS-X",31,WHITE));c.addView(new ChartView(this),new LinearLayout.LayoutParams(-1,dp(210)));page.addView(c);LinearLayout r=new LinearLayout(this);metric(r,"Ortalama/Saat","—");metric(r,"En Yüksek","—");page.addView(r);LinearLayout r2=new LinearLayout(this);metric(r2,"Toplam Süre","—");metric(r2,"Aktif Oturum",running?"Aktif":"Kapalı");page.addView(r2);history();}
