 void invite(){head("DAVET ET KAZAN");LinearLayout c=card();TextView i=t("● ● ●",44,ORANGE);i.setGravity(Gravity.CENTER);c.addView(i);TextView x=t("Arkadaşlarını Davet Et",22,WHITE);x.setGravity(Gravity.CENTER);c.addView(x);TextView p=t("Her uygun davet için\n+%3 kazanç bonusu",24,ORANGE);p.setGravity(Gravity.CENTER);c.addView(p);c.addView(t("Davet bağlantın",12,MUTED));TextView link=t("MARS-X Pool Beta",14,WHITE);link.setBackground(shape(Color.rgb(20,22,27),12));link.setPadding(dp(12),dp(10),dp(12),dp(10));c.addView(link);Button b=btn("WHATSAPP / TELEGRAM / PAYLAŞ");b.setOnClickListener(v->{Intent in=new Intent(Intent.ACTION_SEND);in.setType("text/plain");in.putExtra(Intent.EXTRA_TEXT,"MARS-X Pool Beta");startActivity(Intent.createChooser(in,"Paylaş"));});c.addView(b);c.addView(t("Toplam davet: —\nDavet kazancı: —",14,MUTED));page.addView(c);}
 void settings(){head("AYARLAR");LinearLayout c=card();Switch auto=new Switch(this);auto.setText("Başlangıçta Otomatik Oturum");auto.setTextColor(WHITE);auto.setChecked(appPrefs.getBoolean("auto_start",false));auto.setOnCheckedChangeListener((b,v)->appPrefs.edit().putBoolean("auto_start",v).apply());c.addView(auto);Switch notices=new Switch(this);notices.setText("Bildirimler");notices.setTextColor(WHITE);notices.setChecked(appPrefs.getBoolean("notices",true));notices.setOnCheckedChangeListener((b,v)->appPrefs.edit().putBoolean("notices",v).apply());c.addView(notices);setting(c,"Hesap Bilgileri",()->info("HESAP","Google hesap ve doğrulanmış profil bağlantısı ana hesap servisiyle yönetilir."));setting(c,"Bildirimler",this::notifications);setting(c,"Tema  •  Mars Turuncu",()->{});setting(c,"Dil  •  Türkçe",()->{});setting(c,"Güç ve Performans",this::powerPage);setting(c,"Pil Alt Limiti  •  %15",this::batterySettings);setting(c,"Sıcaklık Limiti  •  43°C",this::thermalSettings);setting(c,"Güvenlik",()->info("GÜVENLİK","Gerçek bakiye yalnızca doğrulanmış sağlayıcı uzlaştırmasından oluşur."));setting(c,"Hakkında  •  v1.0.0",this::about);page.addView(c);}
void batterySettings(){head("PİL OPTİMİZASYONU");LinearLayout c=card();c.addView(t("Alt limit",16,WHITE));SeekBar b=new SeekBar(this);b.setMax(40);b.setProgress(appPrefs.getInt("battery_limit",15));TextView v=t(b.getProgress()+"%",24,ORANGE);b.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar x,int n,boolean u){n=Math.max(5,n);v.setText(n+"%");appPrefs.edit().putInt("battery_limit",n).apply();}public void onStartTrackingTouch(SeekBar x){}public void onStopTrackingTouch(SeekBar x){}});c.addView(v);c.addView(b);c.addView(t("Bu eşik koruma/uyarı ayarıdır; cihazda gizli mining başlatmaz.",12,MUTED));page.addView(c);}
 void thermalSettings(){head("SICAKLIK KONTROLÜ");LinearLayout c=card();c.addView(t("Sıcaklık uyarı sınırı",16,WHITE));SeekBar b=new SeekBar(this);b.setMax(15);int cur=appPrefs.getInt("thermal_limit",43);b.setProgress(cur-35);TextView v=t(cur+"°C",24,ORANGE);b.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar x,int n,boolean u){int z=35+n;v.setText(z+"°C");appPrefs.edit().putInt("thermal_limit",z).apply();}public void onStartTrackingTouch(SeekBar x){}public void onStopTrackingTouch(SeekBar x){}});c.addView(v);c.addView(b);page.addView(c);}
void setting(LinearLayout c,String label,Runnable a){Button b=new Button(this);b.setText(label+"   ›");b.setTextColor(WHITE);b.setTextSize(15);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setAllCaps(false);b.setBackgroundColor(Color.TRANSPARENT);b.setOnClickListener(v->a.run());c.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));}
