 void notifications(){head("BİLDİRİMLER");LinearLayout c=card();c.addView(t("Sistem mesajları",18,WHITE));c.addView(t("Yeni doğrulanmış kazanç, oturum ve güvenlik bildirimleri burada gösterilir.",14,MUTED));c.addView(t("Şu anda yeni bildirim yok",14,GREEN));page.addView(c);}
