 void powerPage(){head("GÜÇ VE PERFORMANS");LinearLayout c=card();c.addView(new GaugeView(this),new LinearLayout.LayoutParams(-1,dp(230)));LinearLayout r=new LinearLayout(this);power=metric(r,"Doğrulanmış Güç","— Sol/s");workers=metric(r,"Aktif Worker","—");c.addView(r);LinearLayout q=new LinearLayout(this);shares=metric(q,"Paylaşılan İş","—");network=metric(q,"Ağ","Bekleniyor");c.addView(q);c.addView(t("Geçerli / geçersiz pay ve ağ ayrıntıları yalnız sağlayıcı tarafından doğrulandığında gösterilir.",12,MUTED));Button adv=btn("GELİŞMİŞ AYARLAR");adv.setOnClickListener(v->settings());c.addView(adv);page.addView(c);refreshDevice();refreshPool();}
 void refreshDevice(){Intent i=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(i==null)return;int level=i.getIntExtra(android.os.BatteryManager.EXTRA_LEVEL,-1),scale=i.getIntExtra(android.os.BatteryManager.EXTRA_SCALE,100),raw=i.getIntExtra(android.os.BatteryManager.EXTRA_TEMPERATURE,-1);int pct=scale>0?Math.round(level*100f/scale):-1;float tc=raw>=0?raw/10f:-1;if(battery!=null)battery.setText("Pil alt limiti %15  •  Cihaz pili "+(pct<0?"—":pct+"%"));int lim=appPrefs.getInt("thermal_limit",43);if(temp!=null)temp.setText(tc<0?lim+"°C sınır":String.format(Locale.getDefault(),"%.1f°C / %d°C",tc,lim));}
 void refreshPool(){final String addr=poolPrefs.getString("address","");if(!VrscAddress.valid(addr)){if(network!=null)network.setText("Havuz verisi • Adres yapılandırılmadı");return;}if(network!=null)network.setText("Havuz verisi • Güncelleniyor…");final long t0=System.currentTimeMillis();io.submit(()->{try{LuckPoolClient.Snapshot x=pool.load(addr);long ms=System.currentTimeMillis()-t0;runOnUiThread(()->{if(power!=null)power.setText(String.format(Locale.getDefault(),"%,.2f Sol/s",x.hashrate));if(workers!=null){int n=0;for(LuckPoolClient.Worker w:x.workers)if(w.online)n++;workers.setText(String.valueOf(n));}if(shares!=null)shares.setText(x.shareValue);if(network!=null)network.setText("Sağlayıcı bağlantısı • "+ms+" ms");});}catch(Exception e){runOnUiThread(()->{if(network!=null)network.setText("Havuz verisi • Kullanılamıyor");});}});}
 public static class EmblemView extends View{Paint p=new Paint(1);public EmblemView(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setStyle(Paint.Style.FILL);p.setColor(ORANGE);Path m=new Path();m.moveTo(w*.15f,h*.82f);m.lineTo(w*.30f,h*.18f);m.lineTo(w*.50f,h*.57f);m.lineTo(w*.70f,h*.18f);m.lineTo(w*.85f,h*.82f);m.lineTo(w*.68f,h*.82f);m.lineTo(w*.63f,h*.50f);m.lineTo(w*.50f,h*.78f);m.lineTo(w*.37f,h*.50f);m.lineTo(w*.32f,h*.82f);m.close();c.drawPath(m,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(4,w*.018f));RectF r=new RectF(w*.10f,h*.32f,w*.90f,h*.70f);c.save();c.rotate(-14,w/2,h/2);c.drawOval(r,p);c.restore();}} public static class GaugeView extends View{Paint p=new Paint(1);public GaugeView(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),cx=w/2,cy=h*.62f,r=Math.min(w,h)*.38f;p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeWidth(Math.max(16,w*.055f));p.setColor(Color.rgb(55,31,18));RectF a=new RectF(cx-r,cy-r,cx+r,cy+r);c.drawArc(a,150,240,false,p);p.setColor(ORANGE);c.drawArc(a,150,120,false,p);p.setStyle(Paint.Style.FILL);p.setColor(WHITE);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(w*.11f);c.drawText("⚡",cx,cy,p);p.setTextSize(w*.05f);p.setColor(MUTED);c.drawText("DOĞRULANMIŞ GÜÇ",cx,cy+h*.15f,p);}} public static class MarsView extends View{Paint p=new Paint(1);public MarsView(Context c){super(c);}protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),cx=w/2,cy=h*.48f,r=Math.min(w,h)*.31f;p.setStyle(Paint.Style.FILL);p.setShader(new RadialGradient(cx-r*.3f,cy-r*.35f,r*1.4f,new int[]{Color.rgb(255,151,55),Color.rgb(181,54,12),Color.rgb(40,8,5)},null,Shader.TileMode.CLAMP));c.drawCircle(cx,cy,r,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(5,w*.018f));p.setColor(ORANGE);RectF o=new RectF(cx-r*1.35f,cy-r*.45f,cx+r*1.35f,cy+r*.45f);c.save();c.rotate(-18,cx,cy);c.drawOval(o,p);c.restore();p.setStyle(Paint.Style.FILL);p.setColor(Color.argb(90,0,0,0));c.drawCircle(cx+r*.28f,cy-r*.16f,r*.13f,p);c.drawCircle(cx-r*.25f,cy+r*.2f,r*.09f,p);}}
 public static class ChartView extends View{Paint p=new Paint(1);public ChartView(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setStrokeWidth(1);p.setColor(Color.rgb(36,40,45));for(int i=1;i<5;i++)c.drawLine(0,h*i/5,w,h*i/5,p);p.setColor(ORANGE);p.setStrokeWidth(5);Path q=new Path();q.moveTo(0,h*.75f);for(int i=1;i<=12;i++){float x=w*i/12f;float y=h*(.72f-(i%4)*.025f);q.lineTo(x,y);}c.drawPath(q,p);p.setColor(Color.argb(35,255,112,8));q.lineTo(w,h);q.lineTo(0,h);q.close();c.drawPath(q,p);}}
 public static class MultiChartView extends View{Paint p=new Paint(1);public MultiChartView(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),top=h*.12f,bottom=h*.84f;p.setStrokeWidth(1);p.setColor(Color.rgb(38,41,46));for(int i=0;i<5;i++){float y=top+(bottom-top)*i/4;c.drawLine(0,y,w,y,p);}for(int i=0;i<7;i++){float x=w*i/6;c.drawLine(x,top,x,bottom,p);}int[] cs={Color.rgb(30,144,255),Color.rgb(255,55,90),ORANGE};for(int k=0;k<3;k++){p.setColor(cs[k]);p.setStrokeWidth(4);p.setStyle(Paint.Style.STROKE);Path q=new Path();for(int i=0;i<7;i++){float x=w*i/6f;float base=.72f-k*.08f;float y=h*(base-(i%4)*(.035f+k*.008f));if(i==0)q.moveTo(x,y);else q.lineTo(x,y);}c.drawPath(q,p);p.setStyle(Paint.Style.FILL);for(int i=0;i<7;i++){float x=w*i/6f;float base=.72f-k*.08f;float y=h*(base-(i%4)*(.035f+k*.008f));c.drawCircle(x,y,5,p);}}p.setTextSize(w*.035f);p.setColor(MUTED);p.setTextAlign(Paint.Align.LEFT);c.drawText("Veri bekleniyor",8,h*.97f,p);}}
 public static class BarView extends View{Paint p=new Paint(1);public BarView(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setColor(ORANGE);for(int i=0;i<7;i++){float bw=w/12f,x=w*(i+1)/8f;float bh=h*(.15f+.04f*(i%3));c.drawRoundRect(x-bw/2,h-bh,x+bw/2,h,8,8,p);}}}
 @Override protected void onDestroy(){pool.cancel();io.shutdownNow();timer.removeCallbacksAndMessages(null);super.onDestroy();}
